public with sharing class AccountContactExplorerController {
    @TestVisible
    private static final Integer MAX_ACCOUNTS = 50;

    @TestVisible
    private static final Integer MAX_CONTACTS = 100;

    @AuraEnabled(cacheable=true)
    public static List<Account> getAccounts() {
        try {
            return [
                SELECT Id, Name
                FROM Account
                WITH USER_MODE
                ORDER BY Name
                LIMIT :MAX_ACCOUNTS
            ];
        } catch (Exception e) {
            throw new AuraHandledException('Unable to load accounts.');
        }
    }

    @AuraEnabled(cacheable=true)
    public static List<Contact> getContacts(Id accountId) {
        try {
            if (accountId == null) {
                return new List<Contact>();
            }
            return [
                SELECT Id, FirstName, LastName, Email, Phone
                FROM Contact
                WHERE AccountId = :accountId
                WITH USER_MODE
                ORDER BY LastName, FirstName
                LIMIT :MAX_CONTACTS
            ];
        } catch (Exception e) {
            throw new AuraHandledException('Unable to load contacts.');
        }
    }
}

@IsTest
private class AccountContactExplorerControllerTest {
    @TestSetup
    static void setupTestData() {
        Account testAccount = new Account(Name = 'Test Account');
        insert testAccount;
        insert new List<Contact>{
            new Contact(
                AccountId = testAccount.Id,
                FirstName = 'John',
                LastName = 'Doe',
                Email = 'john@example.com',
                Phone = '555-1234'
            ),
            new Contact(
                AccountId = testAccount.Id,
                FirstName = 'Jane',
                LastName = 'Doe',
                Email = 'jane@example.com',
                Phone = '555-5678'
            )
        };
    }

    @IsTest
    static void testGetAccounts() {
        List<Account> accounts = AccountContactExplorerController.getAccounts();
        System.assertNotEquals(0, accounts.size(), 'Should return at least one account');
    }

    @IsTest
    static void testGetContactsWithAccount() {
        Account testAccount = [SELECT Id FROM Account LIMIT 1];
        List<Contact> contacts = AccountContactExplorerController.getContacts(testAccount.Id);
        System.assertEquals(2, contacts.size(), 'Should return 2 contacts');
    }

    @IsTest
    static void testGetContactsWithoutAccount() {
        List<Contact> contacts = AccountContactExplorerController.getContacts(null);
        System.assertEquals(0, contacts.size(), 'Should return empty list for null account');
    }
}

import { LightningElement, wire, track, api } from 'lwc';
import { getAccounts, getContacts } from '@salesforce/apex/AccountContactExplorerController';

const CONTACT_COLUMNS = [
    { label: 'First Name', fieldName: 'FirstName' },
    { label: 'Last Name', fieldName: 'LastName' },
    { label: 'Email', fieldName: 'Email' },
    { label: 'Phone', fieldName: 'Phone' }
];

const EMPTY_ACCOUNT_OPTION = { label: '-- Select an account --', value: '' };

export default class AccountContactExplorer extends LightningElement {
    @track selectedAccountId = '';
    @track contacts = [];
    @track isLoading = false;
    @track errorMessage = '';
    @track requestId = 0;

    contactColumns = CONTACT_COLUMNS;

    @wire(getAccounts)
    wiredAccounts(result) {
        if (result.data) {
            const options = [EMPTY_ACCOUNT_OPTION];
            result.data.forEach(account => {
                options.push({ label: account.Name, value: account.Id });
            });
            this.accountOptions = options;
        } else if (result.error) {
            this.errorMessage = 'Unable to load accounts.';
        }
    }

    get accountOptions() {
        return this._accountOptions || [];
    }

    set accountOptions(value) {
        this._accountOptions = value;
    }

    get isLoadDisabled() {
        return !this.selectedAccountId || this.isLoading;
    }

    get showLoading() {
        return this.isLoading && this.requestId === this._currentRequestId;
    }

    get showEmpty() {
        return !this.isLoading && this.contacts.length === 0 && this.selectedAccountId && this.requestId === this._currentRequestId;
    }

    get showError() {
        return !!this.errorMessage && this.requestId === this._currentRequestId;
    }

    get showContacts() {
        return this.contacts.length > 0 && this.requestId === this._currentRequestId;
    }

    handleAccountChange(event) {
        this.selectedAccountId = event.detail.value;
        this.requestId++;
        this._currentRequestId = this.requestId;
        this.contacts = [];
        this.errorMessage = '';
        this.isLoading = false;
    }

    loadContacts() {
        this.requestId++;
        this._currentRequestId = this.requestId;
        this.isLoading = true;
        this.errorMessage = '';

        getContacts({ accountId: this.selectedAccountId })
            .then(result => {
                if (this.requestId === this._currentRequestId) {
                    this.contacts = result;
                    this.isLoading = false;
                }
            })
            .catch(error => {
                if (this.requestId === this._currentRequestId) {
                    this.errorMessage = error.body || 'Unable to load contacts.';
                    this.isLoading = false;
                }
            });
    }
}

import { describe, it, expect, jest } from '@jest/globals';
import { createElement } from 'lwc';
import AccountContactExplorer from 'c/accountContactExplorer';
import { getAccounts, getContacts } from '@salesforce/apex/AccountContactExplorerController';

const mockGetAccounts = require('@salesforce/apex/AccountContactExplorerController.getAccounts');
const mockGetContacts = require('@salesforce/apex/AccountContactExplorerController.getContacts');

jest.mock('@salesforce/apex/AccountContactExplorerController', () => {
    const { getAccounts, getContacts } = jest.requireActual('@salesforce/apex/AccountContactExplorerController');
    return {
        getAccounts: jest.fn(getAccounts),
        getContacts: jest.fn(getContacts)
    };
});

describe('AccountContactExplorer', () => {
    afterEach(() => {
        jest.clearAllMocks();
    });

    it('renders account selector with empty option', () => {
        const element = createElement('c-account-contact-explorer', {
            is: AccountContactExplorer
        });
        document.body.appendChild(element);

        const combobox = element.shadowRoot.querySelector('lightning-combobox');
        expect(combobox).not.toBeNull();
        expect(combobox.options.length).toBeGreaterThan(0);
        expect(combobox.options[0].value).toBe('');
        expect(combobox.options[0].label).toBe('-- Select an account --');
    });

    it('disables load button when no account is selected', () => {
        const element = createElement('c-account-contact-explorer', {
            is: AccountContactExplorer
        });
        document.body.appendChild(element);

        const loadButton = element.shadowRoot.querySelector('lightning-button');
        expect(loadButton.disabled).toBe(true);
    });

    it('enables load button when account is selected', () => {
        const element = createElement('c-account-contact-explorer', {
            is: AccountContactExplorer
        });
        document.body.appendChild(element);

        const combobox = element.shadowRoot.querySelector('lightning-combobox');
        combobox.value = 'testAccountId';
        element.selectedAccountId = 'testAccountId';

        const loadButton = element.shadowRoot.querySelector('lightning-button');
        expect(loadButton.disabled).toBe(false);
    });

    it('shows loading state when contacts are being loaded', async () => {
        const element = createElement('c-account-contact-explorer', {
            is: AccountContactExplorer
        });
        document.body.appendChild(element);

        const combobox = element.shadowRoot.querySelector('lightning-combobox');
        combobox.value = 'testAccountId';
        element.selectedAccountId = 'testAccountId';

        mockGetContacts.mockResolvedValueOnce([
            { Id: '1', FirstName: 'John', LastName: 'Doe', Email: 'john@example.com', Phone: '555-1234' }
        ]);

        const loadButton = element.shadowRoot.querySelector('lightning-button');
        loadButton.click();

        await Promise.resolve();
        const loadingSpinner = element.shadowRoot.querySelector('[data-state="loading"]');
        expect(loadingSpinner).not.toBeNull();
    });

    it('shows empty state when no contacts are found', async () => {
        const element = createElement('c-account-contact-explorer', {
            is: AccountContactExplorer
        });
        document.body.appendChild(element);

        const combobox = element.shadowRoot.querySelector('lightning-combobox');
        combobox.value = 'testAccountId';
        element.selectedAccountId = 'testAccountId';

        mockGetContacts.mockResolvedValueOnce([]);

        const loadButton = element.shadowRoot.querySelector('lightning-button');
        loadButton.click();

        await Promise.resolve();
        const emptyState = element.shadowRoot.querySelector('[data-state="empty"]');
        expect(emptyState).not.toBeNull();
    });

    it('shows error state when contact loading fails', async () => {
        const element = createElement('c-account-contact-explorer', {
            is: AccountContactExplorer
        });
        document.body.appendChild(element);

        const combobox = element.shadowRoot.querySelector('lightning-combobox');
        combobox.value = 'testAccountId';
        element.selectedAccountId = 'testAccountId';

        mockGetContacts.mockRejectedValueOnce(new Error('Test error'));

        const loadButton = element.shadowRoot.querySelector('lightning-button');
        loadButton.click();

        await Promise.resolve();
        const errorAlert = element.shadowRoot.querySelector('lightning-alert');
        expect(errorAlert).not.toBeNull();
        expect(errorAlert.message).toBe('Test error');
    });

    it('prevents stale responses from overwriting current state', async () => {
        const element = createElement('c-account-contact-explorer', {
            is: AccountContactExplorer
        });
        document.body.appendChild(element);

        const combobox = element.shadowRoot.querySelector('lightning-combobox');
        combobox.value = 'testAccountId';
        element.selectedAccountId = 'testAccountId';

        mockGetContacts.mockResolvedValueOnce([
            { Id: '1', FirstName: 'John', LastName: 'Doe', Email: 'john@example.com', Phone: '555-1234' }
        ]);

        const loadButton = element.shadowRoot.querySelector('lightning-button');
        loadButton.click();

        await Promise.resolve();

        combobox.value = 'newAccountId';
        element.selectedAccountId = 'newAccountId';

        mockGetContacts.mockResolvedValueOnce([
            { Id: '2', FirstName: 'Jane', LastName: 'Doe', Email: 'jane@example.com', Phone: '555-5678' }
        ]);

        loadButton.click();

        await Promise.resolve();

        const contactRows = element.shadowRoot.querySelectorAll('[data-role="contact-results"] lightning-datatable tr');
        expect(contactRows.length).toBe(1);
        expect(contactRows[0].textContent).toContain('John');
    });

    it('clears state and shows guidance when selection is cleared', async () => {
        const element = createElement('c-account-contact-explorer', {
            is: AccountContactExplorer
        });
        document.body.appendChild(element);

        const combobox = element.shadowRoot.querySelector('lightning-combobox');
        combobox.value = 'testAccountId';
        element.selectedAccountId = 'testAccountId';

        mockGetContacts.mockResolvedValueOnce([
            { Id: '1', FirstName: 'John', LastName: 'Doe', Email: 'john@example.com', Phone: '555-1234' }
        ]);

        const loadButton = element.shadowRoot.querySelector('lightning-button');
        loadButton.click();

        await Promise.resolve();

        combobox.value = '';
        element.selectedAccountId = '';

        const loadButtonAfterClear = element.shadowRoot.querySelector('lightning-button');
        expect(loadButtonAfterClear.disabled).toBe(true);

        const contactResults = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(contactResults).toBeNull();

        const guidance = element.shadowRoot.querySelector('lightning-alert');
        expect(guidance).not.toBeNull();
        expect(guidance.message).toBe('Select an account before loading contacts.');
    });
});
